const SECRET_NAMES = new Set(SECRET_FIELD_NAMES.map((name) => name.toLowerCase()));

/** Limit głębokości domyka cykle i obiekty o nieznanym kształcie. */
const MAX_REDACTION_DEPTH = 8;

function redactValue(value: unknown, depth: number): unknown {
  if (depth >= MAX_REDACTION_DEPTH || value === null || typeof value !== 'object') {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map((item) => redactValue(item, depth + 1));
  }

  const redacted: Record<string, unknown> = {};

  for (const [key, item] of Object.entries(value)) {
    redacted[key] = SECRET_NAMES.has(key.toLowerCase())
      ? REDACTION_PLACEHOLDER
      : redactValue(item, depth + 1);
  }

  return redacted;
}

export function redactSecretFields(
  source: Record<string, unknown>,
): Record<string, unknown> {
  const redacted: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(source)) {
    redacted[key] = SECRET_NAMES.has(key.toLowerCase())
      ? REDACTION_PLACEHOLDER
      : redactValue(value, 1);
  }

  return redacted;
}
```

