function countLines(lines: readonly string[]): Map<string, number> {
  const counts = new Map<string, number>();

  for (const line of lines) {
    if (line.trim().length === 0) {
      continue;
    }

    counts.set(line, (counts.get(line) ?? 0) + 1);
  }

  return counts;
}

/** Nadwyżka krotności `left` nad `right` — zero wystąpień to też nadwyżka. */
function surplus(
  left: Map<string, number>,
  right: Map<string, number>,
  skip: (line: string) => boolean,
): readonly string[] {
  const result: string[] = [];

  for (const [line, count] of left) {
    if (skip(line)) {
      continue;
    }

    const extra = count - (right.get(line) ?? 0);

    for (let index = 0; index < extra; index += 1) {
      result.push(line);
    }
  }

  return result;
}

